// Dashboard.js

import React, { useState, useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { motion } from "framer-motion";
import {
  fetchDashboardStats,
  fetchRecentChats,
  fetchAvailableDoctors,
} from "../../redux/actions/dashboardActions";
import { fetchNotifications } from "../../redux/actions/notificationActions";
import { getProfile } from "../../redux/actions/authActions";
import Loader from "../../components/common/Loader";
import ChatSidebar from "../../components/chat/ChatSidebar";
import NotificationDropdown from "../../components/notifications/NotificationDropdown";
import { formatDistanceToNow } from "date-fns";
import {
  FiUser,
  FiMessageSquare,
  FiBell,
  FiRefreshCw,
  FiActivity,
  FiArrowRight,
  FiPhoneCall,
  FiVideo,
  FiCalendar,
} from "react-icons/fi";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

const Dashboard = () => {
  const dispatch = useDispatch();
  const [loading, setLoading] = useState(true);

  const {
    stats,
    recentChats,
    availableDoctors,
    loading: dashboardLoading,
  } = useSelector((state) => state.dashboard);
  const { notifications } = useSelector((state) => state.notifications);
  const { user } = useSelector((state) => state.auth);

  useEffect(() => {
    const loadData = async () => {
      await Promise.all([
        dispatch(fetchDashboardStats()),
        dispatch(fetchRecentChats()),
        dispatch(fetchAvailableDoctors()),
        dispatch(fetchNotifications()),
        dispatch(getProfile()),
      ]);
      setLoading(false);
    };
    loadData();
  }, [dispatch]);

  if (loading || dashboardLoading) {
    return <Loader />;
  }

  // --------------------
  // Render Recent Messages (changed fullName -> full_name)
  // --------------------
  const renderRecentMessages = recentChats?.map((chat, index) => {
    const lastMessage = chat.messages?.[chat.messages?.length - 1];
    const sender = lastMessage?.sender;

    return (
      <motion.div
        key={index}
        className="flex justify-between items-center border-b border-gray-200 p-3 hover:bg-gray-50 transition-all cursor-pointer"
        whileHover={{ scale: 1.02 }}
      >
        <div>
          <p className="font-semibold text-gray-800">
            {sender?.full_name || "Unknown"}
          </p>
          <p className="text-gray-500 text-sm">
            {lastMessage?.content?.slice(0, 40)}...
          </p>
        </div>
        <span className="text-xs text-gray-400">
          {formatDistanceToNow(new Date(lastMessage?.createdAt))} ago
        </span>
      </motion.div>
    );
  });

  // --------------------
  // Render Recent Chats (changed fullName -> full_name)
  // --------------------
  const renderRecentChats = recentChats?.map((chat, index) => {
    const otherParticipant =
      chat.participants?.find((p) => p._id !== user?._id) || {};

    return (
      <motion.div
        key={index}
        className="border rounded-lg p-3 shadow-sm bg-white hover:shadow-md transition-all"
      >
        <div className="flex items-center justify-between">
          <div>
            <h4 className="font-semibold text-gray-800">
              {otherParticipant?.full_name || "Unknown"}
            </h4>
            <p className="text-sm text-gray-500">{chat.lastMessage}</p>
          </div>
          <Button variant="outline" size="sm">
            <FiMessageSquare className="mr-1" /> Chat
          </Button>
        </div>
      </motion.div>
    );
  });

  // --------------------
  // Stats Cards (changed fullName -> full_name)
  // --------------------
  const statsCards = [
    {
      label: "Total Users",
      value: stats?.totalUsers || 0,
      icon: <FiUser className="text-blue-600 text-2xl" />,
    },
    {
      label: "Active Chats",
      value: stats?.activeChats || 0,
      icon: <FiMessageSquare className="text-green-600 text-2xl" />,
    },
    {
      label: "Total Doctors",
      value: stats?.totalDoctors || 0,
      icon: <FiActivity className="text-red-600 text-2xl" />,
    },
  ];

  return (
    <div className="p-6 bg-gray-100 min-h-screen">
      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-3xl font-bold text-gray-800">Dashboard</h2>
        <div className="flex items-center gap-3">
          <NotificationDropdown notifications={notifications} />
          <Button variant="outline">
            <FiRefreshCw className="mr-1" /> Refresh
          </Button>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        {statsCards.map((card, idx) => (
          <Card
            key={idx}
            className="shadow-md border-t-4 border-blue-500 bg-white"
          >
            <CardContent className="flex items-center justify-between p-5">
              <div>
                <p className="text-gray-500 text-sm">{card.label}</p>
                <h3 className="text-2xl font-bold text-gray-800">
                  {card.value}
                </h3>
              </div>
              {card.icon}
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Welcome User (changed fullName -> full_name) */}
      <div className="mb-8">
        <Card className="shadow-md bg-gradient-to-r from-blue-50 to-white border-blue-100">
          <CardContent className="flex justify-between items-center p-6">
            <div>
              <h3 className="text-xl font-semibold text-gray-800">
                Welcome back, {user?.full_name || "User"} 👋
              </h3>
              <p className="text-gray-500">
                Here’s an overview of your activity today.
              </p>
            </div>
            <img
              src="/dashboard-illustration.svg"
              alt="dashboard"
              className="w-32 h-32 object-contain"
            />
          </CardContent>
        </Card>
      </div>

      {/* Recent Chats and Doctors */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2">
          <h3 className="text-lg font-semibold text-gray-700 mb-3">
            Recent Chats
          </h3>
          <div className="space-y-4">{renderRecentChats}</div>
        </div>

        {/* Available Doctors (changed fullName -> full_name, consultationFee -> consultation_fee) */}
        <div>
          <h3 className="text-lg font-semibold text-gray-700 mb-3">
            Available Doctors
          </h3>
          <div className="space-y-4">
            {availableDoctors?.map((doctor, index) => (
              <motion.div
                key={index}
                className="border rounded-lg bg-white p-4 shadow-sm hover:shadow-md transition-all"
                whileHover={{ scale: 1.02 }}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <h4 className="font-semibold text-gray-800">
                      {doctor.full_name}
                    </h4>
                    <p className="text-sm text-gray-500">
                      {doctor.specialization}
                    </p>
                    <p className="text-xs text-gray-400">
                      ₹{doctor.consultation_fee}
                    </p>
                  </div>
                  <div className="text-right space-y-2">
                    <Button variant="outline" size="sm">
                      <FiPhoneCall className="mr-1" /> Call
                    </Button>
                    <Button variant="outline" size="sm">
                      <FiVideo className="mr-1" /> Video
                    </Button>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="mt-10">
        <h3 className="text-lg font-semibold text-gray-700 mb-3">
          Quick Actions
        </h3>
        <div className="flex flex-wrap gap-4">
          <Button className="flex items-center">
            <FiMessageSquare className="mr-2" /> Start New Chat
          </Button>
          <Button className="flex items-center" variant="outline">
            <FiCalendar className="mr-2" /> Schedule Appointment
          </Button>
          <Button className="flex items-center" variant="outline">
            <FiArrowRight className="mr-2" /> View Reports
          </Button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
